#include <iostream>
struct Num {
    int x;
    explicit Num(int v) : x(v) {}
    Num& operator+=(const Num& other) { x += other.x; return *this; }
};
int main() {
    Num a(1), b(2), c(4);
    (a += b) += c;
    std::cout << a.x << ' ' << b.x;
}

